    fn apply_aqua_libc_replacement(
        mut pkg: AquaPackage,
        target_os: &str,
        libc: Option<String>,
    ) -> AquaPackage {
        let Some(libc) = libc else {
            return pkg;
        };
        if target_os != "linux" {
            return pkg;
        }
        let Some(linux) = pkg.replacements.get_mut("linux") else {
            return pkg;
        };
        if is_aqua_linux_libc_replacement(linux) {
            let libc = if libc == "musl" { "musl" } else { "gnu" };
            let prefix = linux
                .strip_suffix("-gnu")
                .or_else(|| linux.strip_suffix("-musl"))
                .unwrap_or("unknown-linux");
            *linux = format!("{prefix}-{libc}");
        }
        pkg
    }

    fn apply_selected_asset_libc_replacement(
        pkg: AquaPackage,
        target_os: &str,
        filename: &str,
    ) -> AquaPackage {
        let tokens = asset_name_tokens(filename);
        let libc = if tokens.iter().any(|token| token == "musl") {
            Some("musl")
        } else if tokens
            .iter()
            .any(|token| matches!(token.as_str(), "gnu" | "glibc"))
        {
            Some("gnu")
        } else {
            None
        };
        Self::apply_aqua_libc_replacement(pkg, target_os, libc.map(str::to_string))
    }

    fn apply_var_options(pkg: AquaPackage, opts: &AquaOptions<'_>) -> Result<AquaPackage> {
