    fn test_lock_asset_validation_preserves_explicit_libc() {
        let musl = "tool-1.0.0-x86_64-unknown-linux-musl.tar.gz";
        let gnu = "tool-1.0.0-x86_64-unknown-linux-gnu.tar.gz";

        assert!(!asset_name_matches_expected(
