pub(crate) struct InstallContext {
    pub config: Arc<Config>,
    pub ts: Arc<Toolset>,
    pub pr: Arc<dyn SingleReport>,
    pub force: bool,
    pub dry_run: bool,
    /// require lockfile URLs to be present; fail if not
    pub locked: bool,
    pub before_date: Option<Timestamp>,
    /// One install context belongs to exactly one tool request, so this cache is
    /// intentionally unkeyed. Every caller must use that same request.
    pub(crate) dependency_context: OnceCell<InstallDependencyContext>,
}

impl InstallContext {
    /// Resolve the dependency context for this install's single tool request.
    pub(crate) async fn dependency_context(
        &self,
        request: &ToolRequest,
    ) -> Result<&InstallDependencyContext> {
        self.dependency_context
            .get_or_try_init(|| InstallDependencyContext::resolve(&self.config, request))
            .await
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::toolset::{ToolSource, parse_tool_options};

    fn request(tool: &str, options: &str) -> ToolRequest {
        ToolRequest::new_with_options(
            Arc::new(BackendArg::from(tool)),
            "1.0.0",
            parse_tool_options(options),
            ToolSource::Argument,
        )
        .unwrap()
    }

    fn names(declarations: &InstallDependencyDeclarations) -> Vec<String> {
        declarations.iter().map(|ba| ba.short.clone()).collect()
    }

    #[tokio::test]
    async fn backend_dependencies_include_required_optional_and_recursive_collection() {
        let _config = Config::get().await.unwrap();
        let declarations = install_dependency_declarations(&request("cargo:eza", ""));
        declarations.validate().unwrap();
        let names = names(&declarations);
        assert!(names.contains(&"rust".to_string()));
        assert!(names.contains(&"cargo-binstall".to_string()));
        assert!(names.contains(&"sccache".to_string()));
    }

    #[tokio::test]
    async fn per_tool_dependencies_are_included() {
        let _config = Config::get().await.unwrap();
        let declarations = install_dependency_declarations(&request(
            "http:example",
            r#"depends=["node","python"]"#,
        ));
        declarations.validate().unwrap();
        assert_eq!(names(&declarations), vec!["node", "python"]);
    }

    #[tokio::test]
    async fn backend_and_per_tool_dependencies_are_unioned_deterministically() {
        let _config = Config::get().await.unwrap();
        let declarations = install_dependency_declarations(&request(
            "cargo:eza",
            r#"depends=["python","rust","python"]"#,
        ));
        declarations.validate().unwrap();
        assert_eq!(
            names(&declarations),
    BTreeMap<String, PkgxPackageInfo>,
    bool,
);

/// Resolve lock info for a single tool/platform combination.
///
/// Returns a tuple of (short_name, version, backend_full, platform, info_or_error, options,
/// conda_packages, pkgx_packages, error_is_fatal).
/// Does not log errors — callers decide the appropriate log level.
pub(crate) async fn resolve_tool_lock_info(
    ba: crate::cli::args::BackendArg,
    tv: ToolVersion,
    platform: Platform,
    backend: Option<crate::backend::ABackend>,
) -> LockResolutionResult {
    let target = PlatformTarget::new(platform.clone());
    let error_is_fatal = backend
        .as_ref()
        .is_some_and(|backend| backend.get_type() == BackendType::Conda);

    let (info, options, conda_packages, pkgx_packages) = if let Some(backend) = backend {
        let options = match backend.resolve_lockfile_options(&tv.request, &target) {
            Ok(options) => options,
            Err(e) => {
                return (
                    ba.short.clone(),
                    tv.version.clone(),
                    ba.stored_full(),
                    platform,
                    Err(e.to_string()),
                    BTreeMap::new(),
                    BTreeMap::new(),
                    BTreeMap::new(),
                    error_is_fatal,
                );
            }
        };
        match crate::env::with_install_env(
            tv.install_env(),
            backend.resolve_lock_info(&tv, &target),
        )
        .await
        {
            Ok(info) => {
                let conda_packages = if backend.get_type() == BackendType::Conda {
                    let conda_backend = CondaBackend::from_arg(ba.clone());
                    match conda_backend.resolve_conda_packages(&tv, &target).await {
                        Ok(packages) => packages,
                        Err(e) => {
                            return (
                                ba.short.clone(),
                                tv.version.clone(),
                                ba.stored_full(),
                                platform,
                                Err(format!(
                                    "failed to resolve conda packages for {} on {}: {}",
                                    ba.short,
                                    target.to_key(),
                                    e
                                )),
                                options,
                                BTreeMap::new(),
                                BTreeMap::new(),
                                error_is_fatal,
                            );
                        }

