    pub(crate) fn record(self) -> Result<()> {
        packslip_pins::record(
            &self.project,
            Observed {
                scheme: &self.scheme,
                key_id: &self.key_id,
                issuer: self.issuer.as_deref(),
                attested_by: &self.attested_by,
                provenance: self.provenance,
